validator:
function validate(input) {
  const [{ Cinema = [] }] = input;
  const seats = new Set();
  for (const [id, free] of Cinema) {
    if (id === null) return 'Every seat needs a seat_id.';
    if (seats.has(id)) return `seat_id ${id} appears twice.`;
    seats.add(id);
    if (free !== 0 && free !== 1) return `free must be 0 or 1 (seat ${id}).`;
  }
  for (let id = 1; id <= seats.size; id++) if (!seats.has(id)) return `seat_id values must be 1..${seats.size} with no gaps; ${id} is missing.`;
  return null;
}

generator:
function generate(rand, size) {
  const n = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const pFree = size === 'small' ? 0.35 + rand() * 0.45 : 0.5;
  const Cinema = [];
  for (let id = 1; id <= n; id++) Cinema.push([id, rand() < pFree ? 1 : 0]);
  // Rows may be stored in any order; shuffle some sets so the ORDER BY matters.
  if (rand() < 0.5) {
    for (let i = Cinema.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [Cinema[i], Cinema[j]] = [Cinema[j], Cinema[i]];
    }
  }
  return [{ Cinema }];
}
